   316	/** Initialize our pusher subscriptions to listen for someone typing in a report. */
   317	function subscribeToReportTypingEvents(reportID: string) {
   318	    if (!reportID) {
   319	        return;
   320	    }
   321	
   322	    // Make sure we have a clean Typing indicator before subscribing to typing events
   323	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   324	
   325	    const pusherChannelName = getReportChannelName(reportID);
   326	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   327	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
   328	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   329	        // since personal details are keyed by accountID.
   330	        const normalizedTypingStatus = getNormalizedStatus(typingStatus);
   331	        const accountIDOrLogin = Object.keys(normalizedTypingStatus)[0];
   332	
   333	        if (!accountIDOrLogin) {
   334	            return;
   335	        }
   336	
   337	        // Don't show the typing indicator if the user is typing on another platform
   338	        if (Number(accountIDOrLogin) === currentUserAccountID) {
   339	            return;
   340	        }
   341	
   342	        // Use a combo of the reportID and the accountID or login as a key for holding our timers.
   343	        const reportUserIdentifier = `${reportID}-${accountIDOrLogin}`;
   344	        clearTimeout(typingWatchTimers[reportUserIdentifier]);
   345	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, normalizedTypingStatus);
   346	
   347	        // Wait for 1.5s of no additional typing events before setting the status back to false.
   348	        typingWatchTimers[reportUserIdentifier] = setTimeout(() => {
   349	            const typingStoppedStatus: ReportUserIsTyping = {};
   350	            typingStoppedStatus[accountIDOrLogin] = false;
   351	            Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, typingStoppedStatus);
   352	            delete typingWatchTimers[reportUserIdentifier];
   353	        }, 1500);
   354	    }).catch((error: ReportError) => {
   355	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   356	    });
   357	}
