/**
 * This function will be called when a report is displayed from the ReportScreen.
 * It will check if the report is already being loaded and if it's not, it will call openReport.
 */
function openReportIfNecessary(reportID: string, reportActionID = '', isFromDeepLink = false) {
    const reportMetadata = ReportConnection.getAllReportMetadata()?.[`${ONYXKEYS.COLLECTION.REPORT_METADATA}${reportID}`];
    if (reportMetadata?.isLoadingInitialReportActions) {
        return;
    }
    openReport(reportID, reportActionID, [], undefined, '-1', isFromDeepLink);
}

